.reveal-draw path {
  stroke-dasharray: var(--draw-length);
  stroke-dashoffset: var(--draw-length);
}

.reveal-draw__visible path {
  stroke-dashoffset: 0;
  transition: stroke-dashoffset 2.4s var(--ease-app);
}

@media (prefers-reduced-motion: reduce) {
  .reveal-draw path,
  .reveal-draw__visible path {
    stroke-dasharray: none;
    stroke-dashoffset: 0;
    transition: none;
  }
}

