/* La línea divisoria vive en el contenedor de tabs. */
.tabs {
  border-bottom: 1px solid var(--line);
}

/* Cada tab usa el mismo grosor, sin borde inferior propio. */
.tab {
  border: 1px solid transparent;
  border-bottom: 0;
  /* Sube 1px para montarse sobre la línea y taparla. */
  margin-bottom: -1px;
}

.tab[aria-selected="true"] {
  border-color: var(--line);
  background: #fff;
}

code.en:
/* The divider line lives on the tabs container. */
.tabs {
  border-bottom: 1px solid var(--line);
}

/* Every tab uses the same weight, with no bottom border. */
.tab {
  border: 1px solid transparent;
  border-bottom: 0;
  /* Shifts up 1px to sit on the line and cover it. */
  margin-bottom: -1px;
}

.tab[aria-selected="true"] {
  border-color: var(--line);
  background: #fff;
}
